public class Solution {
    public int romanToInt(String s) {
        // не обрабатывает вычитательные пары (IV, IX, XL и т.п.)
        int[] v = new int[256];
        v['I']=1; v['V']=5; v['X']=10; v['L']=50; v['C']=100; v['D']=500; v['M']=1000;
        int sum = 0;
        for (int i = 0; i < s.length(); i++) sum += v[s.charAt(i)];
        return sum;
    }
}
